\nUPDATE dbo.Prompt SET Category = N'przysłowia' WHERE Category IN (N'proverbs', N'przysłowia');\nUPDATE dbo.Prompt SET Category = N'powiedzenia' WHERE Category IN (N'idioms', N'powiedzenia');\nUPDATE dbo.Prompt SET Category = N'zwierzęta' WHERE Category IN (N'animals', N'zwierzęta');\nUPDATE dbo.Prompt SET Category = N'przedmioty' WHERE Category IN (N'objects', N'food', N'przedmioty');\nUPDATE dbo.Prompt SET Category = N'czynności' WHERE Category IN (\n    N'activities', N'everyday activities', N'everyday situations', N'events', N'games', N'general',\n    N'czynności', N'codzienne czynności', N'codzienne sytuacje', N'wydarzenia', N'gry'\n);\n
